<?php
if(!defined('ABSPATH'))exit;
/** TUFF BEATZ Studio OS V15.6 — Controlled Automation Runtime */
function tuff_beatz_v156_jobs(){ $v=get_option('_tb_v156_jobs',array());return is_array($v)?$v:array(); }
function tuff_beatz_v156_log(){ $v=get_option('_tb_v156_log',array());return is_array($v)?$v:array(); }
function tuff_beatz_v156_write_log($row){$l=tuff_beatz_v156_log();$row['event_id']=wp_generate_uuid4();$row['time']=current_time('mysql');$row['user_id']=get_current_user_id();array_unshift($l,$row);update_option('_tb_v156_log',array_slice($l,0,100),false);}
function tuff_beatz_v156_catalog(){return array(
 'refresh_intelligence'=>array('domain'=>'INTELLIGENCE','label'=>'Refresh executive intelligence','mode'=>'automatic','description'=>'Recalculate read-only strategic/business intelligence from current records.'),
 'generate_plan'=>array('domain'=>'PLANNING','label'=>'Generate strategic planning snapshot','mode'=>'automatic','description'=>'Generate current risks, opportunities and objective portfolio without mutating business records.'),
 'execution_review'=>array('domain'=>'EXECUTION','label'=>'Review strategic execution board','mode'=>'approval','description'=>'Queue a producer decision to review approved/active strategic initiatives.'),
 'communication_draft'=>array('domain'=>'COMMUNICATION','label'=>'Prepare communication draft','mode'=>'approval','description'=>'Queue a human-approved communication drafting workflow; no message is sent by this runtime.')
 );}
function tuff_beatz_v156_enqueue($key){$c=tuff_beatz_v156_catalog();if(!isset($c[$key]))return new WP_Error('unknown_job','Unknown automation job.');$job=$c[$key];$policy=function_exists('tuff_beatz_v155_mode')?tuff_beatz_v155_mode($job['domain']):'manual';if(in_array($policy,array('manual','blocked'),true))return new WP_Error('policy_denied','Automation policy denies runtime execution.');$jobs=tuff_beatz_v156_jobs();$id=wp_generate_uuid4();$status=$policy==='automatic'?'ready':'pending_approval';$jobs[$id]=array('id'=>$id,'key'=>$key,'domain'=>$job['domain'],'label'=>$job['label'],'policy'=>$policy,'status'=>$status,'created_at'=>current_time('mysql'),'created_by'=>get_current_user_id(),'approved_at'=>'','approved_by'=>0,'completed_at'=>'','result'=>'');update_option('_tb_v156_jobs',$jobs,false);tuff_beatz_v156_write_log(array('action'=>'queued','job_id'=>$id,'job_key'=>$key,'status'=>$status));return $id;}
function tuff_beatz_v156_execute($id){$jobs=tuff_beatz_v156_jobs();if(!isset($jobs[$id]))return new WP_Error('missing_job','Job not found.');$j=$jobs[$id];if($j['policy']!=='automatic'&&$j['status']!=='approved')return new WP_Error('approval_required','Human approval is required.');$result='';if($j['key']==='refresh_intelligence'){$x=function_exists('tuff_beatz_v151_intelligence')?tuff_beatz_v151_intelligence():array();$result='Executive intelligence refreshed from current records ('.count($x).' top-level signals).';}elseif($j['key']==='generate_plan'){$x=function_exists('tuff_beatz_v153_objectives')?tuff_beatz_v153_objectives():array();$result='Strategic planning snapshot generated ('.count($x).' objectives).';}else{$result='Approved workflow checkpoint recorded. No external mutation was executed.';}$j['status']='completed';$j['completed_at']=current_time('mysql');$j['result']=$result;$jobs[$id]=$j;update_option('_tb_v156_jobs',$jobs,false);tuff_beatz_v156_write_log(array('action'=>'completed','job_id'=>$id,'job_key'=>$j['key'],'status'=>'completed'));return true;}
function tuff_beatz_v156_post(){if(!is_user_logged_in()||!function_exists('tuff_beatz_is_producer_user')||!tuff_beatz_is_producer_user())wp_die('Unauthorized');check_admin_referer('tb_v156_runtime','tb_v156_nonce');$op=sanitize_key($_POST['tb_v156_op']??'');if($op==='queue'){$key=sanitize_key($_POST['job_key']??'');$id=tuff_beatz_v156_enqueue($key);if(!is_wp_error($id)){ $jobs=tuff_beatz_v156_jobs();if(($jobs[$id]['policy']??'')==='automatic')tuff_beatz_v156_execute($id); }}elseif(in_array($op,array('approve','reject','run'),true)){$id=sanitize_text_field($_POST['job_id']??'');$jobs=tuff_beatz_v156_jobs();if(isset($jobs[$id])){$j=$jobs[$id];if($op==='approve'&&$j['status']==='pending_approval'){$j['status']='approved';$j['approved_at']=current_time('mysql');$j['approved_by']=get_current_user_id();$jobs[$id]=$j;update_option('_tb_v156_jobs',$jobs,false);tuff_beatz_v156_write_log(array('action'=>'approved','job_id'=>$id,'job_key'=>$j['key'],'status'=>'approved'));}elseif($op==='reject'&&$j['status']==='pending_approval'){$j['status']='rejected';$jobs[$id]=$j;update_option('_tb_v156_jobs',$jobs,false);tuff_beatz_v156_write_log(array('action'=>'rejected','job_id'=>$id,'job_key'=>$j['key'],'status'=>'rejected'));}elseif($op==='run')tuff_beatz_v156_execute($id);}}wp_safe_redirect(home_url('/business-command/#automation-runtime'));exit;}
add_action('admin_post_tb_v156_runtime','tuff_beatz_v156_post');
function tuff_beatz_v156_panel(){if(!is_page('business-command')||!is_user_logged_in()||!function_exists('tuff_beatz_is_producer_user')||!tuff_beatz_is_producer_user())return;$cat=tuff_beatz_v156_catalog();$jobs=array_reverse(array_slice(tuff_beatz_v156_jobs(),-12,null,true),true);ob_start();?><section class="tb-v156-runtime" id="automation-runtime"><div class="tb-v156-head"><div><small>CONTROLLED AUTOMATION RUNTIME • V15.6</small><h3>Allowlisted Runtime & Approval Queue</h3><p>Only catalogued operations can enter this runtime. Policy-approved read-only jobs may execute automatically; approval-mode jobs stop for producer authorization.</p></div></div><div class="tb-v156-catalog"><?php foreach($cat as $k=>$j):?><form method="post" action="<?php echo esc_url(admin_url('admin-post.php'));?>"><input type="hidden" name="action" value="tb_v156_runtime"><input type="hidden" name="tb_v156_op" value="queue"><input type="hidden" name="job_key" value="<?php echo esc_attr($k);?>"><?php wp_nonce_field('tb_v156_runtime','tb_v156_nonce');?><small><?php echo esc_html($j['domain'].' • '.strtoupper($j['mode']));?></small><strong><?php echo esc_html($j['label']);?></strong><p><?php echo esc_html($j['description']);?></p><button>QUEUE</button></form><?php endforeach;?></div><div class="tb-v156-queue"><h4>Runtime Queue</h4><?php if(!$jobs):?><p>No runtime jobs recorded yet.</p><?php else:foreach($jobs as $j):?><article><div><small><?php echo esc_html($j['domain'].' • '.$j['policy']);?></small><strong><?php echo esc_html($j['label']);?></strong><p><?php echo esc_html($j['result']?:$j['created_at']);?></p></div><b><?php echo esc_html(strtoupper($j['status']));?></b><?php if(in_array($j['status'],array('pending_approval','approved'),true)):?><form method="post" action="<?php echo esc_url(admin_url('admin-post.php'));?>"><input type="hidden" name="action" value="tb_v156_runtime"><input type="hidden" name="job_id" value="<?php echo esc_attr($j['id']);?>"><?php wp_nonce_field('tb_v156_runtime','tb_v156_nonce');?><?php if($j['status']==='pending_approval'):?><button name="tb_v156_op" value="approve">APPROVE</button><button name="tb_v156_op" value="reject">REJECT</button><?php else:?><button name="tb_v156_op" value="run">RUN APPROVED</button><?php endif;?></form><?php endif;?></article><?php endforeach;endif;?></div><p class="tb-v156-foot">V15.6 has no generic arbitrary-action executor. Manual/blocked policy domains cannot be queued through the runtime, and approval-mode jobs cannot execute before explicit producer approval.</p></section><?php $html=ob_get_clean();?><script>document.addEventListener('DOMContentLoaded',function(){var a=document.querySelector('.tb-v155-policy');if(!a||document.querySelector('.tb-v156-runtime'))return;var b=document.createElement('div');b.innerHTML=<?php echo wp_json_encode($html);?>;a.insertAdjacentElement('afterend',b.firstElementChild);var e=document.querySelector('.tb-biz-hero .eyebrow');if(e)e.textContent='TUFF BEATZ • CONTROLLED RUNTIME V15.6';});</script><?php }
add_action('wp_footer','tuff_beatz_v156_panel',22);
function tuff_beatz_v156_css(){if(!is_page('business-command'))return;wp_add_inline_style('tuff-beatz-business-command','.tb-v156-runtime{margin-top:18px;padding:22px;border:1px solid rgba(216,180,90,.2);border-radius:18px;background:#090909}.tb-v156-head small{color:#a48748;font-size:.52rem;letter-spacing:.14em}.tb-v156-head h3{margin:4px 0;color:#e1d6c2;font-family:Cinzel,serif}.tb-v156-head p,.tb-v156-foot,.tb-v156-queue p{color:#756d61;font-size:.55rem;line-height:1.5}.tb-v156-catalog{display:grid;grid-template-columns:repeat(4,1fr);gap:7px;margin-top:14px}.tb-v156-catalog form,.tb-v156-queue article{padding:12px;border:1px solid rgba(255,255,255,.05);border-radius:10px}.tb-v156-catalog small,.tb-v156-queue small{display:block;color:#8f7747;font-size:.43rem}.tb-v156-catalog strong,.tb-v156-queue strong{display:block;margin-top:4px;color:#d7cdbb;font-size:.62rem}.tb-v156-catalog p{min-height:44px;color:#756d61;font-size:.49rem;line-height:1.4}.tb-v156-runtime button{border:1px solid rgba(205,171,84,.3);background:#111;color:#c8aa5a;border-radius:7px;padding:6px 8px;font-size:.44rem;cursor:pointer}.tb-v156-queue{margin-top:14px}.tb-v156-queue h4{color:#cdbb95;font-family:Cinzel,serif;font-size:.72rem}.tb-v156-queue article{display:grid;grid-template-columns:1fr 110px auto;gap:12px;align-items:center;margin-top:6px}.tb-v156-queue article>b{color:#c5a95d;font-size:.46rem}.tb-v156-queue form{display:flex;gap:5px}.tb-v156-foot{margin:10px 0 0}@media(max-width:900px){.tb-v156-catalog{grid-template-columns:1fr 1fr}.tb-v156-queue article{grid-template-columns:1fr}}@media(max-width:560px){.tb-v156-catalog{grid-template-columns:1fr}}');}
add_action('wp_enqueue_scripts','tuff_beatz_v156_css',118);
